
import re

TECHNIQUE_PATTERN = re.compile(
    r"(?<![A-Za-z0-9])T\d{4}(?:\.\d{3})?(?![A-Za-z0-9]|\.\d)"
)

EVIDENCE_ID_PATTERN = re.compile(
    r"(?m)^ID:\s*(T\d{4}(?:\.\d{3})?)\s*$"
)


def find_unverified_ids(answer: str, evidence: str):
    # Trust only explicitly retrieved technique IDs
    allowed_ids = set(EVIDENCE_ID_PATTERN.findall(evidence))

    # Find every technique ID generated by Gemini
    answer_ids = set(TECHNIQUE_PATTERN.findall(answer))

    return sorted(answer_ids - allowed_ids)

def validate_stream(chunks, evidence):
    """Stop streaming when an unsupported MITRE ID is detected."""

    buffer = ""

    for chunk in chunks:
        buffer += chunk

        # Keep incomplete words in the buffer
        while True:
            match = re.search(r"\s", buffer)

            if match is None:
                break

            end = match.end()
            word = buffer[:end]
            buffer = buffer[end:]

            if find_unverified_ids(word, evidence):
                yield (
                    "\n\n[TacticTrail Warning: An unsupported MITRE "
                    "technique ID was detected. The answer was "
                    "stopped and may be incomplete.]"
                )
                return

            yield word

    if buffer:
        if find_unverified_ids(buffer, evidence):
            yield (
                "\n\n[TacticTrail Warning: An unsupported MITRE "
                "technique ID was detected. The answer was "
                "stopped and may be incomplete.]"
            )
        else:
            yield buffer
